    correction: [{"quoi":"القاعدة","math":"نضع أصغر قوّة عاملا مشتركا، فيبقى داخل القوس عدد صغير"},{"quoi":"نُظهر العامل المشترك","math":"<span dir=\"ltr\" class=\"expr\">2<sup>117</sup> = 2<sup>114</sup> × 2<sup>3</sup></span>"},{"quoi":"نُخرج العامل المشترك","math":"<span dir=\"ltr\" class=\"expr\">2<sup>117</sup> - 2<sup>114</sup> = 2<sup>114</sup>(2<sup>3</sup> - 1)</span>"},{"quoi":"نحسب داخل القوس","math":"<span dir=\"ltr\" class=\"expr\">2<sup>3</sup> - 1 = 7</span>"},{"quoi":"نكتب الجداء","math":"<span dir=\"ltr\" class=\"expr\">2<sup>117</sup> - 2<sup>114</sup> = 7 × 2<sup>114</sup></span>"},{"quoi":"نُظهر القاسم 28","math":"<span dir=\"ltr\" class=\"expr\">7 × 2<sup>114</sup> = 28 × 2<sup>112</sup></span>"},{"quoi":"النتيجة","math":"العدد يساوي <span dir=\"ltr\" class=\"expr\">28 × 2<sup>112</sup></span> و منه يقبل القسمة على 28"}],
