    correction: [{"quoi":"القاعدة","math":"نضع أصغر قوّة عاملا مشتركا، فيبقى داخل القوس عدد صغير"},{"quoi":"الحدود متساوية","math":"الحدود 5 متساوية، و جمع 5 حدود متساوية هو ضربها في 5"},{"quoi":"نكتب الجداء","math":"<span dir=\"ltr\" class=\"expr\">2<sup>5</sup> + 2<sup>5</sup> + 2<sup>5</sup> + 2<sup>5</sup> + 2<sup>5</sup> = 5 × 2<sup>5</sup></span>"},{"quoi":"نُظهر القاسم 10","math":"<span dir=\"ltr\" class=\"expr\">5 × 2<sup>5</sup> = 10 × 2<sup>4</sup></span>"},{"quoi":"النتيجة","math":"العدد يساوي <span dir=\"ltr\" class=\"expr\">10 × 2<sup>4</sup></span> و منه يقبل القسمة على 10"}],
