    enonce: "أجب بصواب أو خطأ مع التعليل: باقي القسمة الإقليدية لـ 5843 على 12 هو 11",
    correction: [{"quoi":"نبحث عن الخارج","math":"أكبر مضاعف لـ 12 لا يفوق 5843 هو <span dir=\"ltr\" class=\"expr\">12 × 486</span>"},{"quoi":"نحسب هذا المضاعف","math":"<span dir=\"ltr\" class=\"expr\">12 × 486 = 5832</span>"},{"quoi":"نحسب الباقي","math":"<span dir=\"ltr\" class=\"expr\">5843 - 5832 = 11</span>"},{"quoi":"نتحقّق من الشرط","math":"<span dir=\"ltr\" class=\"expr\">11 &lt; 12</span>"},{"quoi":"نكتب القسمة الإقليدية","math":"<span dir=\"ltr\" class=\"expr\">5843 = 12 × 486 + 11</span>"},{"quoi":"الجواب","math":"صواب"}],
