    enonce: "بيّن أنّ العدد <span dir=\"ltr\" class=\"expr\">4<sup>13</sup> - 2<sup>29</sup></span> يقبل القسمة على 14",
    correction: [{"quoi":"القاعدة","math":"لا يمكن جمع قوّتين إلاّ إذا كان لهما نفس الأساس"},{"quoi":"نوحّد الأساس في الحدّ الأوّل","math":"<span dir=\"ltr\" class=\"expr\">4<sup>13</sup> = 2<sup>26</sup></span>"},{"quoi":"نعيد كتابة العدد","math":"<span dir=\"ltr\" class=\"expr\">4<sup>13</sup> - 2<sup>29</sup> = 2<sup>26</sup> - 2<sup>29</sup></span>"},{"quoi":"نُخرج أصغر قوّة","math":"<span dir=\"ltr\" class=\"expr\">2<sup>26</sup> - 2<sup>29</sup> = 2<sup>26</sup>(1 - 2<sup>3</sup></span>"},{"quoi":"نحسب داخل القوس","math":"<span dir=\"ltr\" class=\"expr\">1 - 2<sup>3</sup> = -7</span>"},{"quoi":"نكتب الجداء","math":"<span dir=\"ltr\" class=\"expr\">4<sup>13</sup> - 2<sup>29</sup> = -7 × 2<sup>26</sup></span>"},{"quoi":"نُظهر القاسم 14","math":"<span dir=\"ltr\" class=\"expr\">-7 × 2<sup>26</sup> = 14 × (-2<sup>25</sup></span>"},{"quoi":"النتيجة","math":"العدد يساوي <span dir=\"ltr\" class=\"expr\">14 × -2<sup>25</sup></span> و منه يقبل القسمة على 14"}],
